		regionButtonDiv.style.borderRadius = "0px 2px 7px 7px";
		regionButtonDiv.style.right = (-borderRadius)+"px";
		regionButtonDiv.style.top = (-borderRadius)+"px";
		regionButtonDiv.style.borderRadius = "0px 2px 7px 7px";
